#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

const ROOT_PACKAGE = path.resolve('package.json');
const LIBS_DIR = path.resolve('libs');

if (!fs.existsSync(ROOT_PACKAGE)) {
  console.error(`Error: Root package.json not found at ${ROOT_PACKAGE}`);
  process.exit(1);
}

const rootPkg = JSON.parse(fs.readFileSync(ROOT_PACKAGE, 'utf8'));
const rootDeps = {
  ...(rootPkg.dependencies || {}),
  ...(rootPkg.devDependencies || {}),
};

function updateDeps(deps) {
  if (!deps) return deps;
  for (const dep of Object.keys(deps)) {
    if (rootDeps[dep]) {
      deps[dep] = rootDeps[dep];
    }
  }
  return deps;
}

function findPackageJsonFiles(dir) {
  const results = [];
  for (const file of fs.readdirSync(dir)) {
    const fullPath = path.join(dir, file);
    if (fs.statSync(fullPath).isDirectory() && !fullPath.includes('node_modules')) {
      results.push(...findPackageJsonFiles(fullPath));
    } else if (file === 'package.json') {
      results.push(fullPath);
    }
  }
  return results;
}

console.log(`Reading versions from root package.json...`);

const libPackages = findPackageJsonFiles(LIBS_DIR);

for (const pkgPath of libPackages) {
  console.log(`→ Updating ${pkgPath}`);
  const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8'));

  pkg.dependencies = updateDeps(pkg.dependencies);
  pkg.devDependencies = updateDeps(pkg.devDependencies);
  pkg.peerDependencies = updateDeps(pkg.peerDependencies);

  fs.writeFileSync(pkgPath, JSON.stringify(pkg, null, 2) + '\n', 'utf8');
}

console.log('Done! All libs package.json files are now aligned with the root package.json.');
